import { createAction, props } from "@ngrx/store";
import { AuthDTO } from '../../Models/auth.dto';

// 1. La acción que dispara el componente cuando el usuario pulsa el botón "Login"
export const loginRequest = createAction('[Auth] Login Request', props<{ credentials: AuthDTO }>()); // Le pasamos el email y password

// 2. La acción que lanzará el Effect si el backend responde con éxito
export const loginSuccess = createAction('[Auth] Login Success', props<{ userId: string; accessToken: string}>());

// 3. La acción que lanzará el Effect si el backend devuelve un error
export const loginFailure = createAction('[Auth] Logout');
